  ('d4bd1a76-7758-5a45-8412-c092985029bf', null, (select id from public.skills where slug = 'read-g12-main-idea-summary'), null, 'hard',
   $q$How does the final paragraph refine the central idea?$q$, $q$[{"text":"It frames sound as a starting point for recovery and suggests a new view of reefs as places to hear as well as see.","is_correct":true},{"text":"It withdraws the earlier findings by admitting that the speakers had no measurable effect on the fish.","is_correct":false,"misconception_token":"contradicts-text"},{"text":"It summarizes the experiment's method so that other scientists can repeat it exactly.","is_correct":false,"misconception_token":"misreads-structure"},{"text":"It shifts the focus to coral replanting as a better method that should replace the sound experiment.","is_correct":false,"misconception_token":"overstates-contrast"}]$q$::jsonb, $q$It frames sound as a starting point for recovery and suggests a new view of reefs as places to hear as well as see.$q$, $q$The paragraph calls the speakers "a head start rather than a cure" and says restoration involves hearing a reef. It recommends combining sound with replanting, not replacing it.$q$, 'draft', '13695ebd-8121-5451-b622-b5bdb0533b5f')
